<script setup lang="ts">
import {ref,onMounted} from 'vue';import {companyOptions,api,date,errorText,statusLabels} from '../api';import {useAuth} from '../stores/auth';import PageHeading from '../components/PageHeading.vue';import StatusBadge from '../components/StatusBadge.vue';import Modal from '../components/Modal.vue';import {Plus,Send,LockKeyhole} from 'lucide-vue-next';
const auth=useAuth(),conversations=ref<any[]>([]),companies=ref<any[]>([]),selected=ref<any>(null),error=ref(''),busy=ref(false),show=ref(false),body=ref(''),internal=ref(false),form=ref({company_id:'',subject:'',body:''});async function load(){try{conversations.value=(await api.get('/conversations')).data;if(selected.value)selected.value=conversations.value.find(c=>c.id===selected.value.id);}catch(e){error.value=errorText(e);}}async function send(){busy.value=true;try{await api.post(`/conversations/${selected.value.id}/messages`,{body:body.value,internal:internal.value});body.value='';await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}async function create(){busy.value=true;try{const d=(await api.post('/conversations',form.value)).data;show.value=false;await load();selected.value=conversations.value.find(c=>c.id===d.id);}catch(e){error.value=errorText(e);}finally{busy.value=false;}}async function status(e:Event){try{await api.patch(`/conversations/${selected.value.id}`,{status:(e.target as HTMLSelectElement).value});await load();}catch(e){error.value=errorText(e);}}onMounted(async()=>{await load();try{companies.value=await companyOptions();}catch(e){error.value=errorText(e);}});
</script>
<template><PageHeading title="Consultas" subtitle="Cada conversación, junto a la empresa que corresponde."><button class="button primary" @click="show=true"><Plus :size="16"/>Nueva consulta</button></PageHeading><p v-if="error" class="error" role="alert">{{error}}</p><div class="conversation-layout"><section class="panel conversation-list"><button class="conversation-item" v-for="c in conversations" :key="c.id" :class="{selected:selected?.id===c.id}" @click="selected=c"><strong>{{c.subject}}</strong><small>{{c.company.name}}</small><StatusBadge :status="c.status"/></button><p v-if="!conversations.length" class="empty">No hay consultas todavía.</p></section><section class="panel" v-if="selected"><div class="panel-heading"><div><h2>{{selected.subject}}</h2><p>{{selected.company.name}}</p></div><select v-if="auth.staff" :value="selected.status" @change="status" aria-label="Estado de consulta"><option v-for="s in ['open','waiting','resolved']" :key="s" :value="s">{{statusLabels[s]}}</option></select></div><div class="messages"><article v-for="m in selected.messages" :key="m.id" class="message" :class="{internal:m.internal}"><div><strong>{{m.user.name}}</strong><span v-if="m.internal"><LockKeyhole :size="12"/>Nota interna</span><small>{{date(m.created_at)}}</small></div><p>{{m.body}}</p></article></div><form class="message-compose" @submit.prevent="send"><label class="sr-only" for="reply">Escribir respuesta</label><textarea id="reply" v-model="body" required maxlength="5000" placeholder="Escribe tu respuesta…"></textarea><div class="actions"><label v-if="auth.staff" class="checkbox"><input type="checkbox" v-model="internal">Nota interna del equipo</label><button class="button primary" :disabled="busy"><Send :size="15"/>Enviar</button></div></form></section><section v-else class="panel empty">Selecciona una consulta para ver la conversación.</section></div><Modal v-if="show" title="Nueva consulta" @close="show=false"><form class="stack-form" @submit.prevent="create"><label>Empresa<select v-model="form.company_id" required><option value="" disabled>Selecciona empresa</option><option v-for="c in companies" :value="c.id" :key="c.id">{{c.name}}</option></select></label><label>Asunto<input v-model="form.subject" required maxlength="180"></label><label>Mensaje<textarea v-model="form.body" required maxlength="5000"></textarea></label><p v-if="error" class="error">{{error}}</p><button class="button primary" :disabled="busy">Crear consulta</button></form></Modal></template>
